source.raw_text:
\begin{tagblock}{defNot,defOr,defAnd,defIf,defIff,defTrue,defFalse,defEx,defAll}
\begin{explain}
A defined symbol is not officially part of the language, but is
introduced as an informal abbreviation: it allows us to abbreviate
formulas which would, if we only used primitive symbols, get quite
long.  This is obviously an advantage.  The bigger advantage, however,
is that proofs become shorter.  If a symbol is primitive, it has to be
treated separately in proofs. The more primitive symbols, therefore,
the longer our proofs.
\end{explain}
\end{tagblock}

target.raw_text:
\begin{tagblock}{defNot,defOr,defAnd,defIf,defIff,defTrue,defFalse,defEx,defAll}
\begin{explain}
Simbol kang ditetepake dudu perangan resmi saka basa, nanging
ditepungake minangka cekakan ora resmi: kanthi simbol kasebut, kita
bisa nyekakake formula kang bakal dawa banget yen mung nggunakake
simbol primitif. Iki cetha migunani. Nanging paedah kang luwih gedhe
yaiku bukti dadi luwih cekak. Yen sawijining simbol iku primitif,
simbol kasebut kudu ditangani dhewe ing bukti. Mula, saya akeh simbol
primitif, saya dawa bukti kita.
\end{explain}
\end{tagblock}

source.raw_text:
\begin{intro}
You may be familiar with different terminology and symbols than the
ones we use above. Logic texts (and teachers) commonly use 
$\sim$, $\neg$, or~!\ for ``negation'', $\wedge$, $\cdot$, or $\&$
for ``conjunction''.  Commonly used symbols for the ``conditional'' or
``implication'' are $\rightarrow$, $\Rightarrow$, and $\supset$.
\iftag{prvIff,defIff}{Symbols for ``biconditional,'' ``bi-implication,''
  or ``(material) equivalence'' are $\leftrightarrow$,
  $\Leftrightarrow$, and $\equiv$.}{}
\iftag{prvFalse,defFalse}{The $\lfalse$ symbol is variously called
  ``falsity,'' ``falsum,'', ``absurdity,'' or ``bottom.''}{}
\iftag{prvTrue,defTrue}{The $\ltrue$ symbol is variously called
  ``truth,'' ``verum,'' or ``top.''}{}

\begin{defn}[Terms]
\ollabel{defn:terms}
The set of \emph{terms}~$\Trm[L]$ of~$\Lang L$ is
defined inductively by:
\begin{enumerate}
\item Every !!{variable} is a term.
\item Every !!{constant} of~$\Lang L$ is a term.
\item If $f$ is an $n$-place !!{function} and $t_1$, \dots, $t_n$
  are terms, then $\Atom{f}{t_1, \ldots, t_n}$ is a term.
\tagitem{limitClause}{
  Nothing else is a term.}{}
\end{enumerate}
A term containing no !!{variable}s is a \emph{closed term}.
\end{defn}

target.raw_text:
\begin{defn}[Term]
\ollabel{defn:terms}
Himpunan \emph{term}~$\Trm[L]$ saka~$\Lang L$
ditemtokake kanthi induktif kaya mangkene:
\begin{enumerate}
\item Saben !!{variable} iku term.
\item Saben !!{constant} saka~$\Lang L$ iku term.
\item Yen $f$ iku !!{function} $n$-panggonan lan $t_1$, \dots, $t_n$
  iku term, mula $\Atom{f}{t_1, \ldots, t_n}$ iku term.
\tagitem{limitClause}{
  Ora ana liyane kang kalebu term.}{}
\end{enumerate}
Term kang ora ngemot !!{variable}s diarani \emph{term katutup}.
\end{defn}

source.raw_text:
\begin{defn}[Formulas]
\ollabel{defn:formulas}
The set of \emph{!!{formula}s}~$\Frm[L]$ of the language~$\Lang L$
is defined inductively as follows:
\begin{enumerate}
\tagitem{prvFalse}{$\lfalse$ is an atomic !!{formula}.}{}

