source.raw_text:
\begin{lem}[\emph{Principle of induction on !!{formula}s}]
    \ollabel{thm:frmind}
    Let $\Lang L$ be a first-order language.
    If some property~$P$ holds for all the atomic !!{formula}s
    and is such that
    %
    \begin{enumerate}
        \tagitem{prvNot}{it holds for $\lnot !A$ whenever it
            holds for~$!A$;}{}
        \tagitem{prvAnd}{it holds for $(!A \land !B)$
            whenever it holds for $!A$ and~$!B$;}{}
        \tagitem{prvOr}{it holds for $(!A \lor !B)$
            whenever it holds for $!A$ and~$!B$;}{}
        \tagitem{prvIf}{it holds for $(!A \lif !B)$
            whenever it holds for $!A$ and~$!B$;}{}
        \tagitem{prvIff}{it holds for $(!A \liff !B)$
            whenever it holds for $!A$ and~$!B$;}{}
        \tagitem{prvEx}{it holds for $\lexists[x][!A]$
            whenever it holds for~$!A$;}{}
        \tagitem{prvAll}{it holds for $\lforall[x][!A]$
            whenever it holds for~$!A$;}{}
  \end{enumerate}
  (assuming $!A$ and $!B$ are !!{formula}s of~$\Lang{L}$),
  then $P$ holds for all formulas in~$\Frm[L]$.
\end{lem}

target.raw_text:
\begin{lem}[\emph{Prinsip induksi tumrap !!{formula}s}]
    \ollabel{thm:frmind}
    Upamana $\Lang L$ iku basa logika tataran kapisan.
    Yen sawijining sipat~$P$ lumaku kanggo kabeh !!{formula}s atomik
    lan nyukupi syarat iki:
    %
    \begin{enumerate}
        \tagitem{prvNot}{sipat iku lumaku kanggo $\lnot !A$ yen
            lumaku kanggo~$!A$;}{}
        \tagitem{prvAnd}{sipat iku lumaku kanggo $(!A \land !B)$
            yen lumaku kanggo $!A$ lan~$!B$;}{}
        \tagitem{prvOr}{sipat iku lumaku kanggo $(!A \lor !B)$
            yen lumaku kanggo $!A$ lan~$!B$;}{}
        \tagitem{prvIf}{sipat iku lumaku kanggo $(!A \lif !B)$
            yen lumaku kanggo $!A$ lan~$!B$;}{}
        \tagitem{prvIff}{sipat iku lumaku kanggo $(!A \liff !B)$
            yen lumaku kanggo $!A$ lan~$!B$;}{}
        \tagitem{prvEx}{sipat iku lumaku kanggo $\lexists[x][!A]$
            yen lumaku kanggo~$!A$;}{}
        \tagitem{prvAll}{sipat iku lumaku kanggo $\lforall[x][!A]$
            yen lumaku kanggo~$!A$;}{}
  \end{enumerate}
  (kanthi anggepan $!A$ lan $!B$ iku !!{formula}s saka~$\Lang{L}$),
  mula $P$ lumaku kanggo kabeh formula ing~$\Frm[L]$.
\end{lem}

