source.raw_text:
\begin{explain}
It is often useful to talk about the !!{formula}s that ``make up'' a
given !!{formula}.  We call these its \emph{!!{subformula}s}.  Any
!!{formula} counts as !!a{subformula} of itself; a subformula of $!A$
other than $!A$ itself is a \emph{proper !!{subformula}}.
\end{explain}

target.raw_text:
\begin{explain}
Kerep migunani kanggo ngrembug !!{formula}s kang nyusun sawijining
!!{formula}. Iki diarani \emph{!!{subformula}s} saka formula kasebut.
Saben !!{formula} dianggep !!a{subformula} saka awake dhewe;
subformula saka $!A$ kang dudu $!A$ dhewe diarani
\emph{!!{subformula} sejati}.
\end{explain}

source.raw_text:
\begin{defn}[Immediate !!^{subformula}]
If $!A$ is !!a{formula}, the \emph{immediate !!{subformula}s}
of $!A$ are defined inductively as follows:
\begin{enumerate}
\item Atomic !!{formula}s have no immediate !!{subformula}s.

target.raw_text:
\begin{defn}[!!^{subformula} Langsung]
Yen $!A$ iku !!a{formula}, \emph{!!{subformula}s langsung}
saka $!A$ ditetepake kanthi induktif kaya mangkene:
\begin{enumerate}
\item !!{formula}s atomik ora nduweni !!{subformula}s langsung.

source.raw_text:
\item \indcase{!A}{(!B \ast !C)}{The immediate !!{subformula}s of
  $\indfrm$ are $!B$ and $!C$ ($\ast$ is any one of the two-place
  connectives).}

target.raw_text:
\item \indcase{!A}{(!B \ast !C)}{!!{subformula}s langsung saka
  $\indfrm$ yaiku $!B$ lan $!C$ ($\ast$ iku salah siji saka konektif
  rong panggonan).}

source.raw_text:
\tagitem{prvEx}{\indcase{!A}{\lexists[x][!B]}{The only immediate
    !!{subformula} of $\indfrm$ is~$!B$.}}{}
\end{enumerate}
\end{defn}

target.raw_text:
\tagitem{prvEx}{\indcase{!A}{\lexists[x][!B]}{Siji-sijine
    !!{subformula} langsung saka $\indfrm$ yaiku~$!B$.}}{}
\end{enumerate}
\end{defn}

source.raw_text:
\begin{defn}[Proper !!^{subformula}]
If $!A$ is !!a{formula}, the \emph{proper !!{subformula}s}
of $!A$ are defined recursively as follows:
\begin{enumerate}
\item Atomic !!{formula}s have no proper !!{subformula}s.

target.raw_text:
\begin{defn}[!!^{subformula} Sejati]
Yen $!A$ iku !!a{formula}, \emph{!!{subformula}s sejati}
saka $!A$ ditetepake kanthi rekursif kaya mangkene:
\begin{enumerate}
\item !!{formula}s atomik ora nduweni !!{subformula}s sejati.

source.raw_text:
\tagitem{prvNot}{\indcase{!A}{\lnot !B}{The proper !!{subformula}s of
    $\indfrm$ are~$!B$ together with all proper !!{subformula}s
    of~$!B$.}}{}

target.raw_text:
\tagitem{prvNot}{\indcase{!A}{\lnot !B}{!!{subformula}s sejati saka
    $\indfrm$ yaiku~$!B$ bebarengan karo kabeh !!{subformula}s sejati
    saka~$!B$.}}{}

source.raw_text:
\item \indcase{!A}{(!B \ast !C)}{The proper !!{subformula}s of
  $\indfrm$ are $!B$, $!C$, together with all proper !!{subformula}s
  of $!B$ and those of~$!C$.}

target.raw_text:
\item \indcase{!A}{(!B \ast !C)}{!!{subformula}s sejati saka
  $\indfrm$ yaiku $!B$, $!C$, bebarengan karo kabeh !!{subformula}s
  sejati saka $!B$ lan saka~$!C$.}

source.raw_text:
\tagitem{prvAll}{\indcase{!A}{\lforall[x][!B]}{The proper
    !!{subformula}s of $\indfrm$ are~$!B$ together with all proper
    !!{subformula}s of~$!B$.}}{}

target.raw_text:
\tagitem{prvAll}{\indcase{!A}{\lforall[x][!B]}{!!{subformula}s
    sejati saka $\indfrm$ yaiku~$!B$ bebarengan karo kabeh
    !!{subformula}s sejati saka~$!B$.}}{}

