source.raw_text:
\begin{prop}
\ollabel{prop:subfrm-trans}
Suppose $!B$ is a subformula of $!A$ and $!C$ is a subformula of $!B$.
Then $!C$ is a subformula of $!A$. In other words, the subformula
relation is transitive.
\end{prop}

target.raw_text:
\begin{prop}
\ollabel{prop:subfrm-trans}
Upamana $!B$ iku subformula saka $!A$ lan $!C$ iku subformula saka $!B$.
Mula $!C$ iku subformula saka $!A$. Kanthi tembung liya, relasi
subformula iku transitif.
\end{prop}

