source.raw_text:
\begin{prop}
\ollabel{prop:count-subfrms}
Suppose $!A$ is a formula with $n$ connectives and quantifiers.
Then $!A$ has at most $2n+1$ subformulas.
\end{prop}

target.raw_text:
\begin{prop}
\ollabel{prop:count-subfrms}
Upamana $!A$ iku formula kanthi $n$ konektif lan kuantor.
Mula $!A$ nduweni paling akeh $2n+1$ subformula.
\end{prop}

