\begin{defn}[Free occurrences of !!a{variable}]
\ollabel{defn:free-occ}
The \emph{free} occurrences of !!a{variable} in !!a{formula} are defined
inductively as follows:
\begin{enumerate}
\item \indcase*{!A}{$!A$ is atomic}{all !!{variable} occurrences in
  $\indfrm$ are free.}

target.raw_text:
\begin{defn}[Muncule bebas sawijining !!a{variable}]
\ollabel{defn:free-occ}
Muncule \emph{bebas} sawijining !!a{variable} ing !!a{formula}
ditetepake kanthi induktif kaya mangkene:
\begin{enumerate}
\item \indcase*{!A}{$!A$ atomik}{kabeh muncule !!{variable} ing
  $\indfrm$ iku bebas.}

source.raw_text:
\item \indcase{!A}{(!B \ast !C)}{the free
  !!{variable} occurrences of $\indfrm$ are those in $!B$
  together with those in~$!C$.}

target.raw_text:
\item \indcase{!A}{(!B \ast !C)}{muncule
  !!{variable} kang bebas ing $\indfrm$ yaiku kang ana ing $!B$
  bebarengan karo kang ana ing~$!C$.}

source.raw_text:
\tagitem{prvAll}{\indcase{!A}{\lforall[x][!B]}{the free !!{variable}
  occurrences in $\indfrm$ are all of those in~$!B$ except for
  occurrences of~$x$.}}{}

target.raw_text:
\tagitem{prvAll}{\indcase{!A}{\lforall[x][!B]}{muncule !!{variable}
  kang bebas ing $\indfrm$ yaiku kabeh kang ana ing~$!B$ kajaba
  muncule~$x$.}}{}

source.raw_text:
\tagitem{prvEx}{\indcase{!A}{\lexists[x][!B]}{the free !!{variable}
  occurrences in $\indfrm$ are all of those in~$!B$ except for
  occurrences of~$x$.}}{}
\end{enumerate}
\end{defn}

target.raw_text:
