\begin{defn}[Substitution in a term]
We define $\Subst{s}{t}{x}$, the result of \emph{substituting} $t$
for every occurrence of~$x$ in $s$, recursively:
\begin{enumerate}
\item \indcase{s}{c}{$\Subst{\indfrm}{t}{x}$ is just $s$.}

target.raw_text:
\begin{defn}[Substitusi ing term]
Kita nemtokake $\Subst{s}{t}{x}$, yaiku asil saka \emph{nyubstitusikake}
$t$ kanggo saben muncule~$x$ ing $s$, kanthi rekursif:
\begin{enumerate}
\item \indcase{s}{c}{$\Subst{\indfrm}{t}{x}$ mung $s$.}

source.raw_text:
\item\indcase{s}{\Atom{f}{t_1, \dots, t_n}}{$\Subst{\indfrmp}{t}{x}$ is
  $\Atom{f}{\Subst{t_1}{t}{x}, \dots, \Subst{t_n}{t}{x}}$.}
\end{enumerate}
\end{defn}

target.raw_text:
\item\indcase{s}{\Atom{f}{t_1, \dots, t_n}}{$\Subst{\indfrmp}{t}{x}$
  yaiku $\Atom{f}{\Subst{t_1}{t}{x}, \dots, \Subst{t_n}{t}{x}}$.}
\end{enumerate}
\end{defn}

source.raw_text:
\begin{defn}
A term~$t$ is \emph{!!{free for}} $x$ in $!A$ if none of the free
occurrences of~$x$ in $!A$ occur in the scope of a quantifier that
binds a variable in~$t$.
\end{defn}

target.raw_text:
\begin{defn}
Term~$t$ iku \emph{!!{free for}} $x$ ing $!A$ yen ora ana muncule
bebas~$x$ ing $!A$ kang dumunung ing cakupan kuantor kang ngiket
sawijining variabel ing~$t$.
\end{defn}

source.raw_text:
