\begin{defn}
  If $s$ is !!a{variable} assignment for !!a{structure}~$\Struct M$
  and $m \in \Domain{M}$, then the assignment~$\Subst{s}{m}{x}$ is the
  variable assignment defined by
  \[\Subst{s}{m}{x}(y) = \begin{cases}
    m & \text{if } y \ident x\\
    s(y) & \text{otherwise}.
  \end{cases}\]
\end{defn}

target.raw_text:
\begin{defn}
  Yen $s$ iku pangaji !!a{variable} kanggo !!a{structure}~$\Struct M$
  lan $m \in \Domain{M}$, mula pangaji~$\Subst{s}{m}{x}$
  yaiku pangaji variabel kang ditetepake dening
  \[\Subst{s}{m}{x}(y) = \begin{cases}
    m & \text{yen } y \ident x\\
    s(y) & \text{yen ora}.
  \end{cases}\]
\end{defn}

