\begin{cor}
\ollabel{cor:sat-sentence}
If $!A$ is !!a{sentence} and $s$ a variable assignment, then
$\Sat{M}{!A}[s]$ iff $\Sat{M}{!A}[s']$ for every variable
assignment~$s'$.
\end{cor}

