\begin{prob}
\DeclareRobustCommand{\VDash}{\mathrel{||}\joinrel\Relbar}  
Suppose $\Lang L$ is a language without !!{function}s. Given a
!!{structure}~$\Struct M$, $c$ !!a{constant} and $a \in \Domain M$,
define $\Struct M[a/c]$ to be the !!{structure} that is just
like~$\Struct M$, except that $\Assign{c}{M[a/c]} = a$. Define
$\Struct M \VDash !A$ for !!{sentence}s~$!A$ by:
\begin{enumerate}
\tagitem{prvFalse}{%
  \indcase{!A}{\lfalse}{not $\Struct{M} \VDash \indfrm$.}}{}

target.raw_text:
\begin{prob}
\DeclareRobustCommand{\VDash}{\mathrel{||}\joinrel\Relbar}
Upamakna $\Lang L$ iku basa tanpa !!{function}s. Yen basa iki durung nduweni cukup simbol konstanta kang ora katon ing formula, gunakna perluasan basa kanthi konstanta anyar cacah tanpa wates. Cathetan koreksi sumber SOL6-F005: klausa kuantor lan panggantos ing latihan iki mbutuhake konstanta anyar, dene basa tanpa fungsi ora mesthi nduweni konstanta kang cukup. Kanggo
!!{structure}~$\Struct M$, $c$ !!a{constant}, lan
$a \in \Domain M$, tetapna $\Struct M[a/c]$ minangka
!!{structure} kang padha karo~$\Struct M$ kajaba
$\Assign{c}{M[a/c]} = a$. Tetepna $\Struct M \VDash !A$
kanggo !!{sentence}s~$!A$ kaya mangkene:
\begin{enumerate}
\tagitem{prvFalse}{%
  \indcase{!A}{\lfalse}{ora $\Struct{M} \VDash \indfrm$.}}{}

source.raw_text:
\item \indcase{!A}{\Atom{R}{d_1, \dots, d_n}}{$\Struct M \VDash \indfrm$
  iff $\langle \Assign{d_1}{M}, \dots, \Assign{d_n}{M} \rangle \in
  \Assign{R}{M}$.}

target.raw_text:
\item \indcase{!A}{\Atom{R}{d_1, \dots, d_n}}{$\Struct M \VDash \indfrm$
  yen lan mung yen $\langle \Assign{d_1}{M}, \dots, \Assign{d_n}{M} \rangle \in
  \Assign{R}{M}$.}

source.raw_text:
\tagitem{prvNot}{%
  \indcase{!A}{\lnot !B}{$\Struct{M} \VDash \indfrm$ iff
    not $\Struct{M} \VDash {!B}$.}}{}

target.raw_text:
\tagitem{prvNot}{%
  \indcase{!A}{\lnot !B}{$\Struct{M} \VDash \indfrm$ yen lan mung yen
    ora $\Struct{M} \VDash {!B}$.}}{}

source.raw_text:
\tagitem{prvAnd}{%
  \indcase{!A}{(!B \land !C)}{$\Struct{M} \VDash
    \indfrm$ iff $\Struct{M} \VDash!B$ and $\Struct{M} \VDash !C$.}}{}

\tagitem{prvOr}{%
  \indcase{!A}{(!B \lor !C)}{$\Struct{M} \VDash \indfrm$ iff
    $\Struct{M} \VDash !B$ or $\Struct{M} \VDash !C$ (or both).}}{}

\tagitem{prvIf}{%
  \indcase{!A}{(!B \lif !C)}{$\Struct{M} \VDash \indfrm$ iff
    not $\Struct {M} \VDash !B$ or $\Struct M \VDash !C$ (or both).}}{}

(This problem shows that it is possible to give a semantics for
first-order logic that makes do without variable assignments.)
\end{prob}

target.raw_text:
