\begin{prop}
A sentence $!A$ is valid iff $\Gamma \Entails !A$ for every set of
sentences~$\Gamma$.
\end{prop}

target.raw_text:
\begin{prop}
Ukara $!A$ valid yen lan mung yen $\Gamma \Entails !A$
kanggo saben himpunan ukara~$\Gamma$.
\end{prop}

source.raw_text:
\begin{prop}
\ollabel{prop:entails-unsat}
$\Gamma \Entails !A$ iff $\Gamma \cup \{\lnot !A\}$ is unsatisfiable.
\end{prop}

target.raw_text:
\begin{prop}
\ollabel{prop:entails-unsat}
$\Gamma \Entails !A$ yen lan mung yen
$\Gamma \cup \{\lnot !A\}$ ora bisa dicukupi.
\end{prop}

source.raw_text:
For the reverse direction, suppose $\Gamma \cup \{ \lnot !A \}$ is
unsatisfiable. So for every !!{structure}~$\Struct M$, either
$\Sat/{M}{\Gamma}$ or $\Sat{M}{!A}$. Hence, for every !!{structure}
$\Struct M$ with $\Sat{M}{\Gamma}$, $\Sat{M}{!A}$, so $\Gamma \Entails
!A$.
\end{proof}

\begin{prob}
\begin{enumerate}
\item Show that $\Gamma \Entails \bot$ iff $\Gamma$ is unsatisfiable.
\item Show that $\Gamma \cup \{!A\} \Entails \bot$ iff $\Gamma \Entails \lnot !A$.
\item Suppose $c$ does not occur in $!A$ or $\Gamma$.  Show that
  $\Gamma \Entails \lforall[x][!A]$ iff $\Gamma \Entails
  \Subst{!A}{c}{x}$.
\end{enumerate}
\end{prob}

target.raw_text:
\begin{prob}
Ing butir kaping telu, formula mung bisa nduweni variabel bebas kang dikuantifikasi, supaya loro sisih relasi akibat semantis iku ukara. Cathetan cakupan SOL6-F007: definisi akibat semantis ing bagean iki mung tumrap ukara; variabel bebas liyane ora kalebu ing latihan generalisasi iki.
\begin{enumerate}
\item Tuduhna yen $\Gamma \Entails \bot$ yen lan mung yen
  $\Gamma$ ora bisa dicukupi.
\item Tuduhna yen $\Gamma \cup \{!A\} \Entails \bot$
  yen lan mung yen $\Gamma \Entails \lnot !A$.
\item Upamakna $c$ ora katon ing $!A$ utawa $\Gamma$.
  Tuduhna yen $\Gamma \Entails \lforall[x][!A]$
  yen lan mung yen $\Gamma \Entails
  \Subst{!A}{c}{x}$.
\end{enumerate}
\end{prob}

source.raw_text:
\begin{prop}
If $\Gamma \subseteq \Gamma'$ and $\Gamma \Entails !A$, then $\Gamma'
\Entails !A$.
\end{prop}

target.raw_text:
\begin{prop}
Yen $\Gamma \subseteq \Gamma'$ lan $\Gamma \Entails !A$,
mula $\Gamma' \Entails !A$.
\end{prop}

source.raw_text:
\begin{proof}
Suppose that $\Gamma \subseteq \Gamma'$ and $\Gamma \Entails !A$. Let
$\Struct M$ be a structure such that $\Sat{M}{\Gamma'}$; then $\Sat{M}{\Gamma}$,
and since $\Gamma \Entails !A$, we get that $\Sat{M}{!A}$. Hence,
whenever $\Sat{M}{\Gamma'}$, $\Sat{M}{!A}$, so $\Gamma' \Entails !A$.
\end{proof}

target.raw_text:
\begin{proof}
Upamakna $\Gamma \subseteq \Gamma'$ lan
$\Gamma \Entails !A$. Upamakna $\Struct M$ iku
struktur kang ndadekake $\Sat{M}{\Gamma'}$;
mula $\Sat{M}{\Gamma}$, lan amarga
$\Gamma \Entails !A$, kita oleh $\Sat{M}{!A}$.
Dadi kapan wae $\Sat{M}{\Gamma'}$, uga
$\Sat{M}{!A}$, mula $\Gamma' \Entails !A$.
\end{proof}

source.raw_text:
\begin{thm}[Semantic Deduction Theorem]
\ollabel{thm:sem-deduction}
$\Gamma \cup \{!A\} \Entails !B$ iff $\Gamma \Entails !A \lif !B$.
\end{thm}

target.raw_text:
\begin{thm}[Teorema Deduksi Semantis]
\ollabel{thm:sem-deduction}
$\Gamma \cup \{!A\} \Entails !B$ yen lan mung yen
$\Gamma \Entails !A \lif !B$.
\end{thm}

source.raw_text:
For the reverse direction, let $\Gamma \Entails !A \lif !B$ and
$\Struct M$ be !!a{structure} so that $\Sat{M}{\Gamma \cup \{ !A
  \}}$. Then $\Sat{M}{\Gamma}$, so $\Sat{M}{!A \lif !B}$, and since
$\Sat{M}{!A}$, $\Sat{M}{!B}$. Hence, whenever $\Sat{M}{\Gamma \cup \{
  !A \} }$, $\Sat{M}{!B}$, so $\Gamma \cup \{ !A \} \Entails !B$.
\end{proof}

\begin{prop}\ollabel{prop:quant-terms}
  Let $\Struct{M}$ be !!a{structure}, and $!A(x)$ !!a{formula} with
  one free variable~$x$, and $t$~a closed term. Then:
  \begin{tagenumerate}{prvEx,prvAll}
    \tagitem{prvEx}{$!A(t) \Entails \lexists[x][!A(x)]$}{}
    \tagitem{prvAll}{$\lforall[x][!A(x)] \Entails !A(t)$}{}
  \end{tagenumerate}
\end{prop}

target.raw_text:
\begin{prop}\ollabel{prop:quant-terms}
  Upamakna $\Struct{M}$ iku !!a{structure},
  lan $!A(x)$ iku !!a{formula} kanthi siji
  variabel bebas~$x$, sarta $t$~term katutup. Mula:
  \begin{tagenumerate}{prvEx,prvAll}
    \tagitem{prvEx}{$!A(t) \Entails \lexists[x][!A(x)]$}{}
    \tagitem{prvAll}{$\lforall[x][!A(x)] \Entails !A(t)$}{}
  \end{tagenumerate}
\end{prop}

source.raw_text:
\begin{proof}
  \begin{tagenumerate}{prvEx,prvAll}
    \tagitem{prvEx}{%
      \iftag{probEx}{Exercise.}{Suppose $\Sat{M}{!A(t)}$. Let $s$ be a
        variable assignment with $s(x) = \Value{t}{M}$. Then
        $\Sat{M}{!A(t)}[s]$ since $!A(t)$ is !!a{sentence}. By
        \olref[ext]{prop:ext-formulas}, $\Sat{M}{!A(x)}[s]$. By
        \olref[ass]{prop:sat-quant},
        $\Sat{M}{\lexists[x][!A(x)]}$.}}{}
    \tagitem{prvAll}{%
      \iftag{probAll}{Exercise.}{Suppose
        $\Sat{M}{\lforall[x][!A(x)]}$. Let $s$ be a variable
        assignment with $s(x) = \Value{t}{M}$. By
        \olref[ass]{prop:sat-quant}, $\Sat{M}{!A(x)}[s]$.  By
        \olref[ext]{prop:ext-formulas}, $\Sat{M}{!A(t)}[s]$. By
        \olref[ass]{prop:sentence-sat-true}, $\Sat{M}{!A(t)}$ since
        $!A(t)$ is !!a{sentence}.}}{}
  \end{tagenumerate}
\end{proof}

