\begin{rem}\ollabel{remark:R}
  Consider $\Struct{R} = \langle\Real, <\rangle$, the !!{structure}
  whose domain is the set $\Real$ of the real numbers, in the !!{language}
  comprising only a 2-place !!{predicate} interpreted as the $<$
  relation over the reals. Clearly $\Struct{R}$ is !!{nonenumerable};
  however, since $\Theory{R}$ is obviously consistent, by the
  L\"owenheim--Skolem theorem it has !!a{enumerable} model, say
  $\Struct{S}$, and by \olref{prop:equiv}, $\Struct{R}
  \equiv \Struct{S}$. Moreover, since $\Struct{R}$ and $\Struct{S}$
  are not isomorphic, this shows that the converse of
  \olref[iso]{thm:isom} fails in general.
\end{rem}

\begin{defn}
  Given two !!{structure}s $\Struct{M}$ and $\Struct{N}$, a
  \emph{partial isomorphism} from $\Struct{M}$ to $\Struct{N}$ is a
  finite partial function $p$ taking arguments in $\Domain M$ and returning
  values in $\Domain N$, which satisfies the isomorphism conditions from
  \olref[iso]{defn:isomorphism} on its domain:
  \begin{enumerate}
  \item $p$ is !!{injective};
  \item for every !!{constant}~$c$: if $p(\Assign{c}{M})$ is defined,
    then $p(\Assign{c}{M}) = \Assign{c}{N}$;
  \item for every $n$-place !!{predicate} $P$: if $a_1$, \dots, $a_n$
    are in the domain of $p$, then $\langle a_1, \dots, a_n\rangle \in
    \Assign P M$ if and only if $\langle p(a_1), \dots, p(a_n) \rangle
    \in \Assign P N$;
  \item for every $n$-place !!{function} $f$: if $a_1$, \dots, $a_n$
    are in the domain of $p$, then $p(\Assign f M (a_1, \dots,a_n))
    = \Assign f N (p(a_1), \dots, p(a_n))$.
  \end{enumerate}
  That $p$ is finite means that $\dom{p}$ is finite.
\end{defn}

target.raw_text:
\begin{defn}
  Yen diwenehi rong !!{structure}s $\Struct{M}$
  lan $\Struct{N}$ kanggo basa kang padha, \emph{isomorfisme parsial}
  saka $\Struct{M}$ menyang $\Struct{N}$
  iku fungsi parsial winates $p$
  kang nampa argumen saka $\Domain M$
  lan ngasilake nilai ing $\Domain N$,
  lan nyukupi syarat-syarat isomorfisme
  saka \olref[iso]{defn:isomorphism}
  ing ranahé:
  \begin{enumerate}
  \item $p$ iku !!{injective};
  \item kanggo saben !!{constant}~$c$:
    yen $p(\Assign{c}{M})$ katetepake,
    mula $p(\Assign{c}{M}) = \Assign{c}{N}$;
  \item kanggo saben $n$-panggonan
    !!{predicate} $P$: yen $a_1$, \dots, $a_n$
    ana ing ranah $p$, mula
    $\langle a_1, \dots, a_n\rangle \in
    \Assign P M$ yen lan mung yen
    $\langle p(a_1), \dots, p(a_n) \rangle
    \in \Assign P N$;
  \item kanggo saben $n$-panggonan
    !!{function} $f$: yen $a_1$, \dots, $a_n$
    ana ing ranah $p$, mula
    $p(\Assign f M (a_1, \dots,a_n))
    = \Assign f N (p(a_1), \dots, p(a_n))$.
  \end{enumerate}
  $p$ winates tegesé $\dom{p}$ winates. Cathetan cakupan: miturut klausa fungsi ing definisi iki, ranah p kudu katutup tumrap fungsi kang diterapake marang tuple saka ranahe. Iki syarat kang luwih mbatesi kanggo fungsi kang duwe orbit tanpa wates; definisi alternatif kang nggunakake isomorfisme antarane substruktur kang dibangkitake ora diganti kanthi meneng ing edhisi iki.
\end{defn}

