\begin{defn}
Let $\Mod(L){!E}$ denote the class $\Setabs{\Struct{M}}{\Struct{M}
  \models_L !E}$. If the !!{language} needs to be made explicit, we
write $\Mod[L](L){!E}$. Two !!{structure}s $\Struct{M}$ and
$\Struct{N}$ for $\Lang{L}$ are \emph{elementarily equivalent in}
$\tuple{L, \models_L}$, written $\Struct{M} \elemequiv[L] \Struct{N}$, if
the same !!{sentence}s from $L(\Lang{L})$ are true in each.
\end{defn}

target.raw_text:
\begin{defn}
Upamana $\Mod(L){!E}$ nglambangake kelas
$\Setabs{\Struct{M}}{\Struct{M} \models_L !E}$. Yen !!{language}
kudu dicethakake, kita nulis $\Mod[L](L){!E}$. Rong !!{structure}s
$\Struct{M}$ lan $\Struct{N}$ kanggo $\Lang{L}$ iku
\emph{ekuivalen elementer ing} $\tuple{L, \models_L}$, ditulis
$\Struct{M} \elemequiv[L] \Struct{N}$, yen !!{sentence}s kang
padha saka $L(\Lang{L})$ bener ing kalorone.
\end{defn}

