\begin{thm}
\ollabel{thm:abstract-p-isom}
Suppose $\tuple{L, \models_L}$ is a normal logic with the
L\"owenheim--Skolem property. Then any two !!{structure}s that are
partially isomorphic are elementarily equivalent in $\tuple{L,
  \models_L}$.
\end{thm}

