\begin{lem}
\ollabel{lem:lindstrom}
Suppose $!E \in L(\Lang{L})$, with $\Lang{L}$ finite, and assume
also that there is an $n \in \Nat$ such that for any two
!!{structure}s $\Struct{M}$ and~$\Struct{N}$, if $\Struct{M} \equiv_n
\Struct{N}$ and $\Struct{M} \models_L !E$ then also $\Struct{N}
\models_L !E$. Then $!E$ is equivalent to a first-order
!!{sentence}, i.e., there is a first-order $!D$ such that
$\Mod(L){!E} = \Mod(L){!D}$.
\end{lem}

target.raw_text:
\begin{lem}
\ollabel{lem:lindstrom}
Upamana $!E \in L(\Lang{L})$, kanthi $\Lang{L}$ winates, lan
upamana uga ana $n \in \Nat$ saengga kanggo sembarang rong
!!{structure}s $\Struct{M}$ lan~$\Struct{N}$, yen $\Struct{M} \equiv_n
\Struct{N}$ lan $\Struct{M} \models_L !E$, mula $\Struct{N}
\models_L !E$. Banjur $!E$ ekuivalen karo !!{sentence}
tataran kapisan, yaiku ana $!D$ tataran kapisan saengga
$\Mod(L){!E} = \Mod(L){!D}$.
\end{lem}

