\begin{defn}
  \ollabel{defn:primitive-recursion} Suppose $f$ is a $k$-place
  function ($k\ge 1$) and $g$ is a $(k+2)$-place function. The
  function defined by \emph{primitive recursion from $f$ and $g$} is
  the $(k+1)$-place function~$h$ defined by the equations
  \begin{align*}
    h(x_0,\dots,x_{k-1},0) & =  f(x_0,\dots,x_{k-1}) \\
    h(x_0,\dots,x_{k-1},y+1) & = g(x_0,\dots,x_{k-1}, y, h(x_0,\dots,x_{k-1}, y))
  \end{align*}
\end{defn}

target.raw_text:
\begin{defn}
  \ollabel{defn:primitive-recursion} Upamana $f$ iku fungsi
  $k$ panggonan ($k\ge 1$) lan $g$ iku fungsi $(k+2)$ panggonan.
  Fungsi kang ditegesi kanthi \emph{rekursi primitif saka $f$ lan $g$}
  iku fungsi $(k+1)$ panggonan~$h$ kang ditemtokake dening
  persamaan iki:
  \begin{align*}
    h(x_0,\dots,x_{k-1},0) & =  f(x_0,\dots,x_{k-1}) \\
    h(x_0,\dots,x_{k-1},y+1) & = g(x_0,\dots,x_{k-1}, y, h(x_0,\dots,x_{k-1}, y))
  \end{align*}
\end{defn}

