source.raw_text:
\begin{prop}
  The exponentiation function $\fn{exp}(x, y) = x^y$ is primitive recursive.
\end{prop}

target.raw_text:
\begin{prop}
  Fungsi pemangkatan $\fn{exp}(x, y) = x^y$ iku rekursif primitif.
\end{prop}

source.raw_text:
\begin{proof}
  We can define $\fn{exp}$ primitive recursively as
  \begin{align*}
    \fn{exp}(x, 0) & = 1\\
    \fn{exp}(x, y+1) & = \Mult(x, \fn{exp}(x,y)).
    \intertext{Strictly speaking, this is not a recursive definition
      from primitive recursive functions. Officially, though, we
      have:}
    \fn{exp}(x, 0) & = f(x)\\
    \fn{exp}(x, y+1) & = g(x, y, \fn{exp}(x,y)).
    \intertext{where}
    f(x) & = \Succ(\Zero(x)) = 1\\
    g(x, y, z) & = \Mult(\Proj{3}{0}(x, y, z), \Proj{3}{2}(x, y, z)) = x \cdot z
  \end{align*}
  and so $f$ and $g$ are defined from primitive recursive functions by
  composition.
\end{proof}

target.raw_text:
\begin{proof}
  Kita bisa netepake $\fn{exp}$ kanthi rekursi primitif kaya mangkene. Ing fungsi iki, nalika pangkat nol asile tansah siji, kalebu nalika basis nol:
  \begin{align*}
    \fn{exp}(x, 0) & = 1\\
    \fn{exp}(x, y+1) & = \Mult(x, \fn{exp}(x,y)).
    \intertext{Miturut syarat kang tliti, iki durung dadi definisi
      rekursif saka fungsi rekursif primitif. Nanging kanthi
      wangun kang cocog karo aturan, kita nduweni:}
    \fn{exp}(x, 0) & = f(x)\\
    \fn{exp}(x, y+1) & = g(x, y, \fn{exp}(x,y)).
    \intertext{ing ngendi}
    f(x) & = \Succ(\Zero(x)) = 1\\
    g(x, y, z) & = \Mult(\Proj{3}{0}(x, y, z), \Proj{3}{2}(x, y, z)) = x \cdot z
  \end{align*}
  mula $f$ lan $g$ ditegesi saka fungsi rekursif primitif
  kanthi komposisi.
\end{proof}

