\begin{defn}
A relation $R(\vec x)$ is said to be primitive recursive if its characteristic
function,
\[
\Char{R}(\vec x) = \left\{
  \begin{array}{ll}
  1 & \mbox{if $R(\vec x)$} \\
  0 & \mbox{otherwise}
  \end{array}
\right.
\]
is primitive recursive.
\end{defn}

target.raw_text:
\begin{defn}
Relasi $R(\vec x)$ diarani rekursif primitif yen fungsi
karakteristike,
\[
\Char{R}(\vec x) = \left\{
  \begin{array}{ll}
  1 & \mbox{yen $R(\vec x)$} \\
  0 & \mbox{yen ora}
  \end{array}
\right.
\]
iku rekursif primitif.
\end{defn}

source.raw_text:
\begin{prop}
  The set of primitive recursive relations is closed under Boolean
  operations, that is, 
  if $P(\vec x)$ and $Q(\vec x)$ are primitive recursive, so are
  \begin{enumerate}
  \item $\lnot P(\vec x)$
  \item $P(\vec x) \land Q(\vec x)$
  \item $P(\vec x) \lor Q(\vec x)$
  \item $P(\vec x) \lif Q(\vec x)$
  \end{enumerate}
\end{prop}

target.raw_text:
\begin{prop}
  Himpunan relasi rekursif primitif katutup tumrap operasi
  Boolean, yaiku yen $P(\vec x)$ lan $Q(\vec x)$ rekursif
  primitif, mula relasi iki uga:
  \begin{enumerate}
  \item $\lnot P(\vec x)$
  \item $P(\vec x) \land Q(\vec x)$
  \item $P(\vec x) \lor Q(\vec x)$
  \item $P(\vec x) \lif Q(\vec x)$
  \end{enumerate}
\end{prop}

source.raw_text:
\begin{proof}
  Suppose $P(\vec x)$ and $Q(\vec x)$ are primitive recursive, i.e.,
  their characteristic functions $\Char{P}$ and $\Char{Q}$ are.  We
  have to show that the characteristic functions of $\lnot P(\vec x)$,
  etc., are also primitive recursive.
  \[
  \Char{\lnot P}(\vec x) = \begin{cases}
    0 & \text{if $\Char{P}(\vec x) = 1$}\\
    1 & \text{otherwise}
  \end{cases}
  \]
  We can define $\Char{\lnot P}(\vec x)$ as $1 \tsub \Char{P}(\vec x)$.
  \[
  \Char{P \land Q}(\vec x) = \begin{cases}
    1 & \text{if $\Char{P}(\vec x) = \Char{Q}(\vec x) = 1$}\\
    0 & \text{otherwise}
  \end{cases}
  \]
  We can define $\Char{P \land Q}(\vec x)$ as $\Char{P}(\vec x) \cdot
  \Char{Q}(\vec x)$ or as $\fn{min}(\Char{P}(\vec x), \Char{Q}(\vec
  x))$. Similarly, 
  \begin{align*}
    \Char{P \lor Q}(\vec x) & = \fn{max}(\Char{P}(\vec x), \Char{Q}(\vec x)) \text{ and}\\
    \Char{P \lif Q}(\vec x) & = \fn{max}(1 \tsub
  \Char{P}(\vec x), \Char{Q}(\vec x)).
  \end{align*}
\end{proof}

target.raw_text:
\begin{proof}
  Upamana $P(\vec x)$ lan $Q(\vec x)$ rekursif primitif,
  yaiku fungsi karakteristike $\Char{P}$ lan $\Char{Q}$
  rekursif primitif. Kita kudu nuduhake yen fungsi
  karakteristik saka $\lnot P(\vec x)$ lan sakbanjure
  uga rekursif primitif.
  \[
  \Char{\lnot P}(\vec x) = \begin{cases}
    0 & \text{yen $\Char{P}(\vec x) = 1$}\\
    1 & \text{yen ora}
  \end{cases}
  \]
  Kita bisa netepake $\Char{\lnot P}(\vec x)$ minangka
  $1 \tsub \Char{P}(\vec x)$.
  \[
  \Char{P \land Q}(\vec x) = \begin{cases}
    1 & \text{yen $\Char{P}(\vec x) = \Char{Q}(\vec x) = 1$}\\
    0 & \text{yen ora}
  \end{cases}
  \]
  Kita bisa netepake $\Char{P \land Q}(\vec x)$ minangka
  $\Char{P}(\vec x) \cdot
  \Char{Q}(\vec x)$ utawa minangka $\fn{min}(\Char{P}(\vec x), \Char{Q}(\vec
  x))$. Kanthi cara kang padha,
  \begin{align*}
    \Char{P \lor Q}(\vec x) & = \fn{max}(\Char{P}(\vec x), \Char{Q}(\vec x)) \text{ lan}\\
    \Char{P \lif Q}(\vec x) & = \fn{max}(1 \tsub
  \Char{P}(\vec x), \Char{Q}(\vec x)).
  \end{align*}
\end{proof}

source.raw_text:
\begin{prop}
  The set of primitive recursive relations is closed under bounded
  quantification, i.e., if $R(\vec x, z)$ is a primitive recursive
  relation, then so are the relations
  \begin{align*}
    & \bforall{z < y}{R(\vec x, z)} \text{ and}\\
    & \bexists{z < y}{R(\vec x, z)}.
  \end{align*}
  $\bforall{z < y}{R(\vec x, z)}$ holds of $\vec x$ and $y$ if and
  only if $R(\vec x, z)$ holds for every~$z$ less than~$y$, and
  similarly for $\bexists{z < y}{R(\vec x, z)}$.
\end{prop}

target.raw_text:
\begin{prop}
  Himpunan relasi rekursif primitif katutup tumrap
  kuantifikasi mawa wates, yaiku yen $R(\vec x, z)$
  relasi rekursif primitif, mula relasi iki uga:
  \begin{align*}
    & \bforall{z < y}{R(\vec x, z)} \text{ lan}\\
    & \bexists{z < y}{R(\vec x, z)}.
  \end{align*}
  $\bforall{z < y}{R(\vec x, z)}$ bener kanggo $\vec x$
  lan $y$ yen lan mung yen $R(\vec x, z)$ bener kanggo
  saben~$z$ kang kurang saka~$y$; semono uga kanggo
  $\bexists{z < y}{R(\vec x, z)}$.
\end{prop}

