\begin{defn}
  A Turing machine~$M$ computes the partial function $f\colon \Nat^k
  \pto \Nat$ iff, 
  \begin{enumerate}
    \item $M$ halts on input $\TMstroke^{n_1}\concat\TMblank\concat
    \dots \concat\TMblank\concat\TMstroke^{n_k}$ with output $\TMstroke^{m}$ if $f(n_1, \dots, n_k) = m$.
    \item $M$ does not halt at all, or with an output that is not a
    single block of~$\TMstroke$'s if $f(n_1, \dots, n_k)$ is undefined.
  \end{enumerate}
\end{defn}

target.raw_text:
\begin{defn}
  Mesin Turing~$M$ ngitung fungsi parsial $f\colon \Nat^k
  \pto \Nat$ yen lan mung yen
  \begin{enumerate}
    \item $M$ mandheg nalika nampa input $\TMstroke^{n_1}\concat\TMblank\concat
    \dots \concat\TMblank\concat\TMstroke^{n_k}$ kanthi output $\TMstroke^{m}$ yen $f(n_1, \dots, n_k) = m$.
    \item $M$ ora mandheg babar pisan, utawa mandheg kanthi
    output kang dudu siji blok~$\TMstroke$, yen
    $f(n_1, \dots, n_k)$ ora ditegesi.
  \end{enumerate}
Cathetan panyunting: mandheg tanpa output kang ditegesi miturut konvensi panandha kiwa uga kalebu ora menehi output sah.
\end{defn}

source.raw_text:
\begin{defn}\ollabel{defn:disciplined}
A Turing machine~$M$ is \emph{disciplined} iff
\begin{enumerate}
    \item it has a designated single halting state~$h$,
    \item it halts, if it halts at all, while scanning square~$1$,
    \item it never erases the $\TMendtape$ symbol on square~$0$, and
    \item it never attempts to move left from square~$0$.
\end{enumerate}
\end{defn}

target.raw_text:
\begin{defn}\ollabel{defn:disciplined}
Mesin Turing~$M$ diarani \emph{tertib} yen lan mung yen
\begin{enumerate}
    \item nduwé siji kahanan mandheg mligi~$h$,
    \item yen mandheg, sirah maca-nulis lagi maca kothak~$1$,
    \item ora tau mbusak simbol $\TMendtape$ ing kothak~$0$, lan
    \item ora tau nyoba mindhah sirah maca-nulis menyang kiwa saka kothak~$0$.
\end{enumerate}
\end{defn}

