\begin{editorial}
 Material in this part covers the incompleteness theorems. It depends
 on material in the parts on first-order logic (esp., the proof
 system), the material on recursive functions (in the computability
 part).  It is based on Jeremy Avigad's notes with revisions by Richard Zach.
\end{editorial}

\begin{defn}
A set of !!{sentence}s~$\Gamma$ is a \emph{theory} if it is closed
under entailment, i.e., if $\Gamma = \Setabs{!A}{\Gamma \Entails
!A}$.
\end{defn}

target.raw_text:
\begin{defn}
Himpunan !!{sentence}s~$\Gamma$ diarani
\emph{teori} yen katutup tumrap akibat semantis,
yaiku yen $\Gamma = \Setabs{!A}{\Gamma \Entails
!A}$.
\end{defn}

source.raw_text:
\begin{defn}\ollabel{def:standard-model}
The \emph{standard model of arithmetic} is the !!{structure}~$\Struct
N$ defined as follows:
\begin{enumerate}
\item $\Domain N = \Nat$
\item $\Assign{\Obj 0}{N} = 0$
\item $\Assign{\Obj \prime}{N}(n) = n + 1$ for all $n \in \Nat$
\item $\Assign{\Obj +}{N}(n, m) = n + m$ for all $n, m \in \Nat$
\item $\Assign{\Obj \times}{N}(n, m) = n\cdot m$ for all $n, m \in \Nat$
\item $\Assign{\Obj <}{N} = \Setabs{\tuple{n, m}}{n \in \Nat, m \in
  \Nat, n < m}$
\end{enumerate}
\end{defn}

target.raw_text:
\begin{defn}\ollabel{def:standard-model}
\emph{Model baku aritmetika} yaiku
!!{structure}~$\Struct N$ kang ditegesi kaya mangkene:
\begin{enumerate}
\item $\Domain N = \Nat$
\item $\Assign{\Obj 0}{N} = 0$
\item $\Assign{\Obj \prime}{N}(n) = n + 1$ kanggo kabeh $n \in \Nat$
\item $\Assign{\Obj +}{N}(n, m) = n + m$ kanggo kabeh $n, m \in \Nat$
\item $\Assign{\Obj \times}{N}(n, m) = n\cdot m$ kanggo kabeh $n, m \in \Nat$
\item $\Assign{\Obj <}{N} = \Setabs{\tuple{n, m}}{n \in \Nat, m \in
  \Nat, n < m}$
\end{enumerate}
\end{defn}

source.raw_text:
\begin{defn}
A theory~$\Gamma$ is \emph{axiomatized} by~$\Gamma_0$ iff
\[
\Gamma = \Setabs{!A}{\Gamma_0 \Entails !A}
\]
\end{defn}

target.raw_text:
\begin{defn}
Teori~$\Gamma$ \emph{diaksiomatisasi}
dening~$\Gamma_0$ yen lan mung yen
\[
\Gamma = \Setabs{!A}{\Gamma_0 \Entails !A}
\]
\end{defn}

source.raw_text:
\begin{defn}
A theory $\Gamma$ is \emph{!!{complete}} iff for every
!!{sentence}~$!A$ in its language, either $\Gamma \Entails !A$ or
$\Gamma \Entails \lnot !A$.
\end{defn}

target.raw_text:
\begin{defn}
Teori $\Gamma$ diarani \emph{!!{complete}}
yen lan mung yen kanggo saben
!!{sentence}~$!A$ ing basane,
$\Gamma \Entails !A$ utawa
$\Gamma \Entails \lnot !A$.
\end{defn}

source.raw_text:
\begin{explain}
By the Completeness Theorem, $\Gamma \Entails !A$ iff $\Gamma \Proves
!A$, so $\Gamma$ is complete iff for every !!{sentence}~$!A$ in its
language, either $\Gamma \Proves !A$ or $\Gamma \Proves \lnot !A$.
\end{explain}

\begin{defn}
A set $X$ is \emph{!!{decidable}} iff there is a computational procedure
which on input~$x$ returns~$1$ if $x \in X$ and $0$ otherwise.
\end{defn}

target.raw_text:
\begin{defn}
Himpunan $X$ diarani \emph{!!{decidable}}
yen lan mung yen ana prosedur komputasional
kang, kanggo input~$x$, ngasilake~$1$
yen $x \in X$ lan $0$ yen ora.
\end{defn}

source.raw_text:
\begin{defn}
A theory is \emph{!!{axiomatizable}} if it is axiomatized
by !!a{decidable} set of axioms.
\end{defn}

target.raw_text:
\begin{defn}
Teori diarani \emph{!!{axiomatizable}}
yen diaksiomatisasi dening himpunan
aksioma kang !!a{decidable}.
\end{defn}

source.raw_text:
\begin{defn}
A set $X$ is called \emph{!!{computably enumerable}} (!!{c.e.} for
short) iff it is empty or it has a computable enumeration.
\end{defn}

target.raw_text:
\begin{defn}
Himpunan $X$ diarani \emph{!!{computably enumerable}}
(disingkat !!{c.e.}) yen lan mung yen kosong
utawa nduwé enumerasi komputabel.
\end{defn}

source.raw_text:
\begin{defn}
A !!{formula}~$!A(x_1, \dots, x_k, y)$ \emph{!!{represents}} the
function $f\colon \Nat^k \to \Nat$ in~$\Gamma$ iff whenever $f(n_1,
\dots, n_k) = m$, then
\begin{enumerate}
\item $\Gamma \Proves !A(\num{n_1}, \dots, \num{n_k}, \num{m})$, and
\item $\Gamma \Proves \lforall[y](!A(\num{n_1}, \dots, \num{n_k},
y) \lif y = \num{m})$.
\end{enumerate}
\end{defn}

target.raw_text:
\begin{defn}
!!{formula}~$!A(x_1, \dots, x_k, y)$
\emph{!!{represents}} fungsi
$f\colon \Nat^k \to \Nat$ ing~$\Gamma$
yen lan mung yen saben $f(n_1, \dots, n_k) = m$,
mangka
\begin{enumerate}
\item $\Gamma \Proves !A(\num{n_1}, \dots, \num{n_k}, \num{m})$, lan
\item $\Gamma \Proves \lforall[y](!A(\num{n_1}, \dots, \num{n_k},
y) \lif y = \num{m})$.
\end{enumerate}
\end{defn}

source.raw_text:
\begin{defn}
A !!{formula}~$!A(x_1, \dots, x_k)$ \emph{!!{represents}} the
relation $R \subseteq \Nat^k$ iff,
\begin{enumerate}
\item whenever $R(n_1, \dots, n_k)$, $\Gamma \Proves !A(\num{n_1},
\dots, \num{n_k})$, and
\item whenever not $R(n_1, \dots, n_k)$, $\Gamma \Proves \lnot
!A(\num{n_1}, \dots, \num{n_k})$.
\end{enumerate}
\end{defn}

\begin{thm}
If $\Gamma$ is a consistent and !!{axiomatizable} theory in~$\Lang
L_A$ which !!{represents} all computable functions and !!{decidable}
relations, then $\Gamma$ is not !!{complete}.
\end{thm}

\begin{thm}
If $\Gamma$ is a consistent theory that !!{represents} every
!!{decidable} relation, then $\Gamma$ is not !!{decidable}.
\end{thm}

target.raw_text:
\begin{thm}
Yen $\Gamma$ teori konsisten kang !!{represents}
saben relasi !!{decidable}, mula $\Gamma$
ora !!{decidable}.
\end{thm}

source.raw_text:
\begin{proof}
Suppose $\Gamma$ were !!{decidable}. We show that if $\Gamma$
!!{represents} every !!{decidable} relation, it must be inconsistent.

\begin{thm}
If $\Gamma$ is !!{axiomatizable} and !!{complete} it is !!{decidable}.
\end{thm}

target.raw_text:
\begin{thm}
Yen $\Gamma$ !!{axiomatizable} lan
!!{complete}, teori iku !!{decidable}.
\end{thm}

source.raw_text:
\begin{cor}
\ollabel{cor:incompleteness}
If $\Gamma$ is consistent, !!{axiomatizable}, and !!{represents} every
!!{decidable} property, it is not !!{complete}.
\end{cor}

target.raw_text:
\begin{cor}
\ollabel{cor:incompleteness}
Yen $\Gamma$ konsisten, !!{axiomatizable},
lan !!{represents} saben sifat !!{decidable},
teori iku ora !!{complete}.
\end{cor}

source.raw_text:
\begin{proof}
If $\Gamma$ were !!{complete}, it would be !!{decidable} by the
previous theorem (since it is !!{axiomatizable} and consistent). But
since $\Gamma$ !!{represents} every !!{decidable} property, it is not
!!{decidable}, by the first theorem.
\end{proof}

target.raw_text:
\begin{proof}
Yen $\Gamma$ !!{complete}, miturut teorema
sadurunge teori iku bakal !!{decidable}
(amarga !!{axiomatizable} lan konsisten).
Nanging amarga $\Gamma$ !!{represents}
saben sifat !!{decidable}, miturut teorema
kapisan teori iku ora !!{decidable}.
\end{proof}

