\begin{prop}
The following relations are primitive recursive:
\begin{enumerate}
\item $\fn{Fn}(x, n)$ iff $x$ is the code of $\Obj f^n_i$ for
  some~$i$, i.e., $x$ is the code of an $n$-ary !!{function}.
\item $\fn{Pred}(x, n)$ iff $x$ is the code of $\Obj P^n_i$ for
  some~$i$ or $x$ is the code of $\eq$ and $n = 2$, i.e., $x$ is the
  code of an $n$-ary !!{predicate}.
\end{enumerate}
\end{prop}

target.raw_text:
\begin{prop}
Relasi-relasi ing ngisor iki rekursif primitif:
\begin{enumerate}
\item $\fn{Fn}(x, n)$ yen lan mung yen $x$
  iku kode $\Obj f^n_i$ kanggo sawijining~$i$,
  yaiku $x$ iku kode !!{function} aritas~$n$.
\item $\fn{Pred}(x, n)$ yen lan mung yen $x$
  iku kode $\Obj P^n_i$ kanggo sawijining~$i$
  utawa $x$ iku kode $\eq$ lan $n = 2$,
  yaiku $x$ iku kode !!{predicate} aritas~$n$.
\end{enumerate}
\end{prop}

source.raw_text:
\begin{defn}
If $s_0, \dots, s_{n-1}$ is a sequence of symbols, its \emph{G\"odel
  number} is $\tuple{\scode{s_0}, \dots, \scode{s_{n-1}}}$.
\end{defn}

target.raw_text:
\begin{defn}
Yen $s_0, \dots, s_{n-1}$ iku urutan simbol,
\emph{wilangan G\"odel} saka urutan iku yaiku
$\tuple{\scode{s_0}, \dots, \scode{s_{n-1}}}$.
\end{defn}

source.raw_text:
\begin{prop}
\ollabel{prop:term-primrec}
The relations $\fn{Term}(x)$ and $\fn{ClTerm}(x)$ which hold iff $x$
is the G\"odel number of a term or a closed term, respectively, are
primitive recursive.
\end{prop}

target.raw_text:
\begin{prop}
\ollabel{prop:term-primrec}
Relasi $\fn{Term}(x)$ lan $\fn{ClTerm}(x)$,
kang bener yen lan mung yen $x$ iku wilangan
G\"odel saka suku utawa suku katutup,
miturut urutane, iku rekursif primitif.
\end{prop}

Kanggo $\fn{ClTerm}$, cukup tinggalake
klausa kanggo !!{variable}s.
\end{proof}

source.raw_text:
