  \item Kabeh asumsi ing $\delta$ kanthi label~$n$ awujud~$!A$
    (yaiku, kita bisa !!{discharge} asumsi~$!A$ nganggo label~$n$
    ing~$\delta$).
  \end{enumerate}
\end{prop}

