\begin{prop}
  \ollabel{prop:prf-prim-rec}
  Suppose $\Gamma$ is a primitive recursive set of !!{sentence}s.
  Then the relation $\Prf[\Gamma](x, y)$ expressing ``$x$ is the code
  of !!a{derivation}~$\delta$ of $!A$ from !!{undischarged}
  assumptions in~$\Gamma$ and $y$ is the G\"odel number of~$!A$'' is
  primitive recursive.
\end{prop}

target.raw_text:
\begin{prop}
  \ollabel{prop:prf-prim-rec}
  Upamane $\Gamma$ iku himpunan rekursif primitif saka
  !!{sentence}s. Relasi $\Prf[\Gamma](x, y)$ kang nyatakake
  ``$x$ iku kode saka !!a{derivation}~$\delta$ kanggo $!A$
  adhedhasar asumsi kang !!{undischarged} ing~$\Gamma$ lan
  $y$ iku wilangan G\"odel saka~$!A$'' iku rekursif primitif.
\end{prop}

\begin{proof}
  Upamane ``$y \in \Gamma$'' diwenehake dening predikat
  rekursif primitif~$R_\Gamma(y)$. Kita kudu nuduhake yen
  $\Prf[\Gamma](x, y)$, kang bener yen lan mung yen $y$ iku
  wilangan G\"odel saka ukara~$!A$ lan $x$~iku kode saka
  !!{derivation} deduksi natural kanthi !!{formula}
  pungkasan~$!A$ lan kabeh asumsi kang !!{undischarged}
  ana ing~$\Gamma$, iku rekursif primitif.

source.raw_text:
By \olref{prop:deriv}, the property $\fn{Deriv}(x)$ which holds iff
  $x$ is the G\"odel number of a correct !!{derivation}~$\delta$ in
  natural deduction is primitive recursive. Thus we can define
  $\Prf[\Gamma](x, y)$ by
  \begin{align*}
    \Prf[\Gamma](x, y) \defiff {}
    & \fn{Deriv}(x) \land \fn{EndFmla}(x) = y \land {} \\
    & \bforall{z < x}{(\fn{OpenAssum}(z, x) \lif R_\Gamma(z))}.
  \end{align*}
\end{proof}

target.raw_text:
Miturut \olref{prop:deriv}, sifat $\fn{Deriv}(x)$, kang bener
  yen lan mung yen $x$ iku wilangan G\"odel saka
  !!{derivation}~$\delta$ kang bener ing deduksi natural,
  iku rekursif primitif. Mula $\Prf[\Gamma](x, y)$ bisa
  ditetepake dening
  \begin{align*}
    \Prf[\Gamma](x, y) \defiff {}
    & \fn{Deriv}(x) \land \fn{EndFmla}(x) = y \land {} \\
    & \bforall{z < x}{(\fn{OpenAssum}(z, x) \lif R_\Gamma(z))}.
  \end{align*}
\end{proof}

source.raw_text:
\begin{explain}
In order to arithmetize axiomatic !!{derivation}s, we must represent
!!{derivation}s as numbers. Since !!{derivation}s are simply sequences
of !!{formula}s, the obvious approach is to code every !!{derivation}
as the code of the sequence of codes of !!{formula}s in it.
\end{explain}

\begin{ex}
  Consider the very simple !!{derivation}:
  \begin{derivation}
  1. & $!B \lif (!B \lor !A)$ \\
  2. & $(!B \lif (!B \lor !A)) \lif (!A  \lif (!B \lif (!B \lor !A)))$\\
  3. & $!A  \lif (!B \lif (!B \lor !A))$
  \end{derivation}
  The G\"odel number of this !!{derivation} would be
  \begin{align*}
  \openTuple\, 
    & \Gn{!B \lif (!B \lor !A)}, \\
    &\Gn{(!B \lif (!B \lor !A)) \lif (!A  \lif (!B \lif (!B \lor !A)))},\\
    & \Gn{!A  \lif (!B \lif (!B \lor !A))} \,\closeTuple.
  \end{align*}
\end{ex}

