\ollabel{lem:beta}
Ana fungsi $\beta(d,i)$ saengga kanggo saben urutan $a_0$,
\dots,~$a_n$ ana wilangan~$d$ kang ndadekake, kanggo saben $i \le n$,
$\beta(d,i) = a_i$. Kajaba iku, $\beta$ bisa ditegesi saka fungsi
dhasar mung nganggo komposisi lan panggolekan tanpa wates reguler.
\end{lem}

source.raw_text:
\begin{defn}
Two natural numbers $a$ and $b$ are \emph{relatively prime} iff their
greatest common divisor is~$1$; in other words, they have no other
divisors in common.
\end{defn}

target.raw_text:
\begin{defn}
Rong wilangan natural $a$ lan $b$ \emph{relatif prima} yen lan mung yen
faktor bebarengan kang paling gedhe yaiku~$1$; kanthi tembung liya,
ora ana faktor bebarengan liyane.
\end{defn}

source.raw_text:
\begin{defn}
Natural numbers $a$ and $b$ are \emph{congruent modulo~$c$},
$a \equiv b \mod c$, iff $c \mid (a-b)$, i.e., $a$ and $b$ have the
same remainder when divided by~$c$.
\end{defn}

target.raw_text:
\begin{defn}
Wilangan natural $a$ lan $b$ diarani \emph{kongruen modulo~$c$},
$a \equiv b \mod c$, kanthi $c>0$, yen lan mung yen $c \mid (a-b)$, yaiku $a$ lan $b$
nduweni sisa kang padha nalika dipara karo~$c$.
\end{defn}

source.raw_text:
Here is Sunzi's Theorem:
\begin{thm}
Suppose $x_0$, \dots,~$x_n$ are (pairwise) relatively prime. Let
$y_0$, \dots,~$y_n$ be any numbers. Then there is a number $z$ such that
\begin{align*}
z & \equiv y_0 \mod x_0 \\
z & \equiv y_1 \mod x_1 \\
& \vdots  \\
z & \equiv y_n \mod x_n.
\end{align*}
\end{thm}

target.raw_text:
Iki Teorema Sunzi:
\begin{thm}
Upamana $x_0$, \dots,~$x_n$ positif lan relatif prima saben pasangan. Tetepna
$y_0$, \dots,~$y_n$ minangka wilangan sembarang. Mula ana wilangan $z$ saengga
\begin{align*}
z & \equiv y_0 \mod x_0 \\
z & \equiv y_1 \mod x_1 \\
& \vdots  \\
z & \equiv y_n \mod x_n.
\end{align*}
\end{thm}

