\begin{defn}
\ollabel{thm:oconsis-q}
A theory $\Th{T}$ is $\omega$-consistent if the following holds: if
$\lexists[x][!A(x)]$ is any sentence and $\Th{T}$ proves $\lnot
!A(\num 0)$, $\lnot !A(\num 1)$, $\lnot !A(\num 2)$, \dots then $\Th{T}$
does not prove $\lexists[x][!A(x)]$.
\end{defn}

target.raw_text:
\begin{defn}
\ollabel{thm:oconsis-q}
Teori $\Th{T}$ iku $\omega$-konsisten yen kahanan iki kelakon: yen
$\lexists[x][!A(x)]$ iku ukara sembarang lan $\Th{T}$ mbuktekake $\lnot
!A(\num 0)$, $\lnot !A(\num 1)$, $\lnot !A(\num 2)$, \dots mula $\Th{T}$
ora mbuktekake $\lexists[x][!A(x)]$.
\end{defn}

